"""Machine-level lemmas for T12a (generated by mexp.py): n1's base rules and round-1 events (gen_base.py, evs.py),
the restart events and the period events with a variable far side (evs12.py).
  python gen_machine12.py OUT.v"""
import sys, time
from pathlib import Path
from evs12 import *
import evs as N1
import mexp
from gen_base import RULES as BASE

N1_EVENTS = ['H', 'S0', 'E']
EVENTS = ['LP1', 'LP2', 'LP3', 'LP4', 'R1END', 'E0', 'E1', 'E2', 'E3', 'E4', 'E5', 'E6', 'E7', 'E8', 'E10', 'E11', 'E12']


def one(name, S, T, pos, out):
    tree = mexp.explore(S, T, splits=4, positive=pos)
    g = mexp.Gen('X' + name)
    r = mexp.rule_lemma('EV_' + name, S, T, tree, g, progress=False, positive=sorted(pos))
    out += g.lemmas + [r]


def gen(events=None):
    out = []
    t0 = time.time()
    for name, S, T in BASE:
        tree = mexp.explore(S, T, splits=3)
        g = mexp.Gen(name)
        r = mexp.rule_lemma(name, S, T, tree, g, progress=True)
        out += g.lemmas + [r]
    for name in N1_EVENTS:
        e = N1.EV[name]
        one(name, e[0], e[1], frozenset(e[2]) if len(e) > 2 else frozenset(), out)
    for name in (events or EVENTS):
        e = EV[name]
        one(name, e[0], e[1], frozenset(e[2]) if len(e) > 2 else frozenset(), out)
    print('generated in %.1fs, %d lemmas' % (time.time() - t0, len(out)), file=sys.stderr)
    return out


def machine_text(events=None):
    pl.LEMMAS.clear()
    lem = gen(events)
    return ('\n(** ** Crossing lemmas (generated) *)\n\n' + coqgen.crossing_lemmas()
            + '\n(** ** Machine-level lemmas (generated by mexp.py) *)\n\n' + '\n'.join(lem))


if __name__ == '__main__':
    text = header('T12a machine part (development)') + '\n' + machine_text()
    Path(sys.argv[1]).write_text(text, newline='\n')
    print('wrote', sys.argv[1], len(text), 'bytes', file=sys.stderr)
